create extension if not exists pgcrypto;
create table if not exists users(id serial primary key,name text not null,email text unique not null,password_hash text not null,role text not null default 'customer' check(role in('customer','staff','admin')),created_at timestamptz default now());
create table if not exists products(id serial primary key,name text not null,category text not null,description text not null,ingredients text not null,price_cents int not null check(price_cents>0),image text,stock int not null default 100 check(stock>=0),active boolean not null default true,created_at timestamptz default now());
create index if not exists products_cat on products(category) where active;
create table if not exists extras(key text primary key,name text not null,price_cents int not null check(price_cents>=0));
insert into extras values('large','גודל גדול',500),('extra_fruit','תוספת פרי',400),('granola','תוספת גרנולה',300),('protein','תוספת חלבון',500),('oat_milk','חלב שיבולת שועל',300),('coconut_milk','חלב קוקוס',300) on conflict do nothing;
create table if not exists coupons(code text primary key,percent int check(percent between 1 and 100),amount_cents int,min_order_cents int not null default 0,expires_at timestamptz,max_uses int,uses int not null default 0,active boolean not null default true,check((percent is null)<>(amount_cents is null)));
create table if not exists orders(id uuid primary key default gen_random_uuid(),user_id int references users(id),name text not null,email text not null,phone text not null,address text,city text,postal text,notes text,mode text not null check(mode in('pickup','delivery')),coupon_code text,subtotal_cents int not null,discount_cents int not null,fee_cents int not null,total_cents int not null,currency text not null,
status text not null default 'pending_payment' check(status in('pending_payment','payment_confirmed','payment_review','preparing','ready_for_pickup','out_for_delivery','delivered','cancelled')),paypal_order_id text,created_at timestamptz default now(),updated_at timestamptz default now());
create index if not exists orders_user on orders(user_id);create index if not exists orders_status on orders(status,created_at desc);
create table if not exists order_items(id serial primary key,order_id uuid not null references orders(id) on delete cascade,product_id int references products(id),name text not null,options jsonb not null default '{}',unit_cents int not null,qty int not null check(qty>0));
create index if not exists items_order on order_items(order_id);
create table if not exists payments(id serial primary key,order_id uuid not null references orders(id),provider text not null,transaction_id text unique not null,amount_cents int not null,currency text not null,status text not null,created_at timestamptz default now());
create table if not exists payment_events(id serial primary key,event_id text unique not null,type text not null,payload jsonb not null,created_at timestamptz default now());
create table if not exists reviews(id serial primary key,product_id int not null references products(id) on delete cascade,user_id int not null references users(id),rating int not null check(rating between 1 and 5),body text,verified boolean not null default false,status text not null default 'pending' check(status in('pending','approved','rejected')),created_at timestamptz default now(),unique(product_id,user_id));
